--
-- Triggers `hed_shipping`
--
DELIMITER $$
CREATE TRIGGER `trg_generate_shipping_no` BEFORE INSERT ON `hed_shipping` FOR EACH ROW BEGIN
    DECLARE next_number INT;
    DECLARE date_prefix VARCHAR(8);
    
    IF NEW.shipping_no IS NULL OR NEW.shipping_no = '' THEN
        SET date_prefix = DATE_FORMAT(NEW.shipping_date, '%Y%m%d');
        
        SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(shipping_no, '-', -1) AS UNSIGNED)), 0) + 1
        INTO next_number
        FROM hed_shipping
        WHERE shipping_no LIKE CONCAT('SHP-', date_prefix, '-%');
        
        SET NEW.shipping_no = CONCAT('SHP-', date_prefix, '-', LPAD(next_number, 4, '0'));
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_update_shipping_modified` BEFORE UPDATE ON `hed_shipping` FOR EACH ROW BEGIN
    SET NEW.date_modified = NOW();
END
$$
